cd /app && python3 -c "
import pytz
import datetime
tz = pytz.timezone('America/New_York')
# Spring forward: March 13, 2022, 2:00 AM → 3:00 AM
dt = datetime.datetime(2022, 3, 13, 2, 30)
print(f'Nonexistent: {dt}')
try:
    print(f'is_dst=None: {tz.localize(dt, is_dst=None)}')
except Exception as e:
    print(f'is_dst=None Exception: {type(e).__name__}: {e}')
try:
    print(f'is_dst=False: {tz.localize(dt, is_dst=False)}')
except Exception as e:
    print(f'is_dst=False Exception: {type(e).__name__}: {e}')
try:
    print(f'is_dst=True: {tz.localize(dt, is_dst=True)}')
except Exception as e:
    print(f'is_dst=True Exception: {type(e).__name__}: {e}')

# Fall back: Nov 6, 2022, 1:00 AM → 1:00 AM (2 hours)
dt2 = datetime.datetime(2022, 11, 6, 1, 30)
print(f'\\nAmbiguous: {dt2}')
try:
    print(f'is_dst=None: {tz.localize(dt2, is_dst=None)}')
except Exception as e:
    print(f'is_dst=None Exception: {type(e).__name__}: {e}')
try:
    print(f'is_dst=False: {tz.localize(dt2, is_dst=False)}')
except Exception as e:
    print(f'is_dst=False Exception: {type(e).__name__}: {e}')
try:
    print(f'is_dst=True: {tz.localize(dt2, is_dst=True)}')
except Exception as e:
    print(f'is_dst=True Exception: {type(e).__name__}: {e}')
"
